// Functions in a source over 64 KB compile on their first call; each
// case below is one the lazy path must get right. The padding at the
// end only makes the source large.
const out = [];
let counter = 10;
const K = 'k';
function outer(a, b) {
    // captures a parameter, a module-level let, a const, and calls itself
    let local = a + b;
    function inner(x) {
        // a function inside a lazy one: lazy too, capturing through it
        return x + local + counter + K.length;
    }
    local += 1;
    counter += 1;
    return inner(1);
}
out.push(outer(1, 2));
out.push(outer(1, 2));

const fact = function f(n) {
    // a named expression sees its own name
    if (n <= 1) { return 1; }
    return n * f(n - 1);
};
out.push(fact(6), fact.name, fact.length);

var inferred = function (p, q = 2, ...r) {
    // name inference, length up to the first default, arguments, this in an arrow
    const self = this;
    const arrow = () => this === self && arguments.length;
    return [p, q, r.length, arrow()];
};
out.push(inferred.name, inferred.length, JSON.stringify(inferred.call({}, 1, undefined, 3, 4)));

function makeCounters() {
    // a per-iteration let binding captured by each closure
    const fns = [];
    for (let i = 0; i < 3; i++) { fns.push(function () { return i * 100 + fns.length; }); }
    return fns.map((g) => g()).join(',');
}
out.push(makeCounters());

function shadow(counter) {
    // a parameter shadows the outer name; a var in a block shadows too
    if (counter > 0) { var K = 'inner'; }
    return counter + ':' + K;
}
out.push(shadow(5), shadow(0));

function tdz() {
    // reading a let before its declaration throws, through a lazy closure
    function read() { return later; }
    let caught = 'none';
    try { read(); } catch (e) { caught = e.constructor.name; }
    let later = 'set';
    return caught + ',' + read();
}
out.push(tdz());

function Ctor(v) {
    // a constructor compiled on its first new
    this.v = v;
    this.twice = function () { return this.v * 2; };
}
out.push(new Ctor(21).twice(), typeof Ctor.prototype, Ctor.prototype.constructor === Ctor);

function shown(a, b) { return a + b; /* this text comes back from toString, padded to be long enough to be lazy ............................................................................................................................ */ }
out.push(shown.toString().startsWith('function shown(a, b)'), shown(2, 3));

function assignConst() {
    // assigning to a const captured from outside throws
    try { K = 'x'; return 'no'; } catch (e) { return e.constructor.name; }
}
out.push(assignConst());

function Holder() {
    // a long arrow capturing the constructor's this and arguments, and an arrow inside it
    this.v = 7;
    this.get = (k) => {
        const inner = (m) => this.v * m + arguments.length;
        return inner(k) + counter;
    };
}
out.push(new Holder(1, 2).get(3));
const exprArrow = (a, b) => a * b + counter + K.length /* an expression body, padded long enough to be lazy ................................................................................................................................................ */;
out.push(exprArrow(3, 4));
const later = () => { /* an arrow whose free name is declared after it, read only once it is set ................................................................................................................................ */ return afterwards; };
const afterwards = 'after';
out.push(later());

const modules = {
    101(exports, req) {
        // a module factory written as a method, the way a bundle writes them
        exports.value = req(202) + counter;
        exports.again = function () { return exports.value * 2; };
    },
    202() { /* a second method, long enough to be compiled on its first call ........................................................................................................................ */ return 40; },
    get(x) { /* a method named get ............................................................................................................................................................................ */ return 'got ' + x; },
    'quoted key'(y) { /* a string key ........................................................................................................................................................................ */ return y + 1; },
};
const ex = {};
modules[101](ex, (id) => modules[id]());
out.push(ex.value, ex.again(), modules.get(1), modules['quoted key'](1));
class Shape {
    constructor(n) { this.n = n; }
    area(k) { /* a class method, strict, long enough ......................................................................................................................................................... */ return this.n * k + counter; }
    static make() { /* a static method stays eager ......................................................................................................................................................... */ return new Shape(2); }
}
out.push(Shape.make().area(5), typeof Shape.prototype.area.prototype);

console.log(out.join(' '));
